/* From Uiverse.io by andrew-demchenk0 - Tags: loader */
.__UIV_SCOPE__ .loader {
  display: inline-block;
  position: relative;
  width: 80px;
  height: 80px;
}

.__UIV_SCOPE__ .loader .loader_item {
  transform-origin: 40px 40px;
  animation: spinner 1.2s linear infinite;
}

.__UIV_SCOPE__ .loader .loader_item:after {
  content: " ";
  display: block;
  position: absolute;
  top: 3px;
  left: 37px;
  width: 6px;
  height: 18px;
  border-radius: 20%;
  /* try any color u want (yellow, red, lightskyblue ect...) */
  background: green;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(1) {
  transform: rotate(0deg);
  animation-delay: -1.1s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(2) {
  transform: rotate(30deg);
  animation-delay: -1s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(3) {
  transform: rotate(60deg);
  animation-delay: -0.9s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(4) {
  transform: rotate(90deg);
  animation-delay: -0.8s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(5) {
  transform: rotate(120deg);
  animation-delay: -0.7s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(6) {
  transform: rotate(150deg);
  animation-delay: -0.6s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(7) {
  transform: rotate(180deg);
  animation-delay: -0.5s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(8) {
  transform: rotate(210deg);
  animation-delay: -0.4s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(9) {
  transform: rotate(240deg);
  animation-delay: -0.3s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(10) {
  transform: rotate(270deg);
  animation-delay: -0.2s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(11) {
  transform: rotate(300deg);
  animation-delay: -0.1s;
}

.__UIV_SCOPE__ .loader .loader_item:nth-child(12) {
  transform: rotate(330deg);
  animation-delay: 0s;
}

@keyframes spinner {
  0% {
    opacity: 1;
    filter: hue-rotate(0deg);
  }

  100% {
    opacity: 0;
    filter: hue-rotate(360deg);
  }
}
